"""CPU report renderer adapted from the browser-tested factorial index."""
import html
import json

def render_html(entries,summary,include_bundle):
    primary=summary['comparisons']['primary_raw_minus_vae']
    title=f"Raw DINO minus VAE: {primary['difference']*100:+.1f} pp; 95% interval [{primary['ci95'][0]*100:+.1f}, {primary['ci95'][1]*100:+.1f}] pp"
    dataset=json.dumps(entries).replace('</','<\\/')
    bundle='<a href="../complete-vae-evidence.zip" download>Download complete evidence</a>' if include_bundle else ''
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Matched DINO/VAE evidence</title>
<style>body{font:16px system-ui;margin:24px;background:#10151d;color:#e8eef6}a{color:#99c9ff}header{max-width:1100px}select,button{font:inherit;padding:8px;margin:4px;background:#243147;color:inherit;border:1px solid #61718b;border-radius:6px}#grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}article{background:#1a2432;padding:12px;border-radius:10px}video{width:100%;aspect-ratio:1.74}h1{font-size:24px}h2{font-size:16px}small{color:#b6c3d5}.links{display:flex;gap:12px;flex-wrap:wrap}</style>
<header><h1>Matched DINO/VAE</h1><p>'''+html.escape(title)+'''</p><p>All three arms use the same corrected executor. Raw/VAE is primary; Compact/VAE is secondary. Baseline is on top, VAE below.</p><p class="links"><a href="RESULTS.md" download>Download report</a><a href="index.json" download>Download video index</a>'''+bundle+'''</p></header>
<div><select id="comparison"></select><select id="task"></select><select id="seed"></select><select id="outcome"></select><button id="previous">Previous</button><button id="next">Next</button><span id="count"></span></div><div id="grid"></div>
<p><small>Top/bottom labels identify the pair. All three policy cameras; action-index alignment, final-frame hold. No external whole-robot camera. Manual review samples six indices on each first scene; complete videos are available for every pair.</small></p>
<script>const data='''+dataset+''';let page=0;const size=24;const controls=['comparison','task','seed','outcome'];
for(const name of controls){const select=document.getElementById(name);const values=[...new Set(data.map(x=>String(x[name])))];if(name!=='comparison')values.unshift('All');for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}select.onchange=()=>{page=0;render()}}
document.getElementById('comparison').value='primary_raw_minus_vae';
function render(){const rows=data.filter(x=>controls.every(name=>{const value=document.getElementById(name).value;return value==='All'||String(x[name])===value}));page=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));const grid=document.getElementById('grid');grid.replaceChildren();for(const x of rows.slice(page*size,(page+1)*size)){const card=document.createElement('article');const title=document.createElement('h2');title.textContent=`${x.task} · seed ${x.seed} · scene ${x.scene}`;card.append(title);const label=document.createElement('p');label.textContent=`${x.labels.join(' / ')} · ${x.outcome}`;card.append(label);const video=document.createElement('video');video.controls=true;video.preload='none';video.poster=x.preview;video.src=x.video;card.append(video);const links=document.createElement('p');links.className='links';for(const [text,path] of [['Video',x.video],['Preview',x.preview],['Pair data',x.metadata]]){const a=document.createElement('a');a.textContent='Download '+text;a.href=path;a.download='';links.append(a)}card.append(links);grid.append(card)}document.getElementById('count').textContent=`${rows.length} pairs · page ${page+1}/${Math.max(1,Math.ceil(rows.length/size))}`;document.getElementById('previous').disabled=page===0;document.getElementById('next').disabled=(page+1)*size>=rows.length}
document.getElementById('previous').onclick=()=>{page--;render()};document.getElementById('next').onclick=()=>{page++;render()};render();</script></html>'''
